import { defineRouteMiddleware, type StarlightRouteData } from "@astrojs/starlight/route-data";

type SidebarEntry = StarlightRouteData["sidebar"][number];
type HeadEntry = StarlightRouteData["head"][number];

// Autogenerated sidebar groups take their directory name. Mirrored repository
// documents live in reference/generated/; show that group with a real label.
const labels: Record<string, string> = { generated: "Repository documents" };

const relabel = (entries: SidebarEntry[]): void => {
  for (const entry of entries) {
    if (entry.type !== "group") continue;
    entry.label = labels[entry.label] ?? entry.label;
    relabel(entry.entries);
  }
};

const isCanonical = (entry: HeadEntry): boolean =>
  (entry.tag === "link" && entry.attrs?.rel === "canonical") ||
  (entry.tag === "meta" && entry.attrs?.property === "og:url");

/** @public Starlight loads this route middleware by path (astro.config.mjs). */
export const onRequest = defineRouteMiddleware((context) => {
  const route = context.locals.starlightRoute;
  relabel(route.sidebar);
  if (route.entry.id === "index" || route.entry.id === "") {
    // The homepage is a website, not an article.
    for (const entry of route.head) {
      if (entry.tag === "meta" && entry.attrs?.property === "og:type")
        entry.attrs.content = "website";
    }
  }
  if (route.entry.id === "404") {
    // GitHub Pages serves 404.html for every missing path: it has no canonical URL.
    route.head = route.head.filter((entry) => !isCanonical(entry));
    route.head.push({ tag: "meta", attrs: { name: "robots", content: "noindex" }, content: "" });
  }
});
